@Component("admission-handler")
@ProcessingGroup("admission-processing-group")
public class AdmissionEventHandler {
	
	// core constructor
	AdmissionEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAdmissionEvent
     */
    @EventHandler
    public void handle( CreateAdmissionEvent event) {
        entityManager.persist(new Admission(event.getAdmissionId(), event.getAdmitDateTime(), event.getBed(), event.getEncounter(), event.getFacility(), event.getAdmissionType()));
    }

    /*
     * @param	event UpdateAdmissionEvent
     */
    @EventHandler
    public Admission handle( UpdateAdmissionEvent event) {
    	entityManager.merge(new Admission(event.getAdmissionId(), event.getAdmitDateTime(), event.getBed(), event.getEncounter(), event.getFacility(), event.getAdmissionType()));
    }
    
    /*
     * @param	event DeleteAdmissionEvent
     */
    @EventHandler
    public void on( DeleteAdmissionEvent event) {
    	Admission entity = new Admission();
   
    	// ------------------------------------------
    	// apply the AdmissionId
    	// ------------------------------------------
    	entity.setAdmissionId( event.getAdmissionId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AdmissionRepository admissionEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AdmissionEventHandler.class.getName());

}
